SELECT dd.id, dd.device_id AS deviceId, dd.device_code AS deviceCode, d.device_name AS deviceName, dd.plot_id AS plotId, p.plot_name AS plotName, dd.data_json AS dataJson, dd.temperature, dd.humidity, dd.soil_moisture AS soilMoisture, dd.soil_temp AS soilTemp, dd.ph, dd.light_intensity AS lightIntensity, dd.co2, dd.device_status AS deviceStatus, dd.report_time AS reportTime, dd.create_time AS createTime FROM agri_iot_device_data dd LEFT JOIN agri_iot_device d ON dd.device_id = d.id LEFT JOIN agri_iot_plot p ON dd.plot_id = p.id WHERE dd.device_id = #{deviceId}
AND dd.report_time >= #{startTime}
AND dd.report_time <= #{endTime}
ORDER BY dd.report_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM agri_iot_device_data dd
WHERE dd.device_id = #{deviceId}

    AND dd.report_time >= #{startTime}


    AND dd.report_time <= #{endTime}
